import java.util.concurrent.StructuredTaskScope;
import java.util.concurrent.Future;
import java.time.Duration;

public class UserDashboardService {

    record UserProfile(String name, String preferences) {}
    record UserOrders(int orderCount) {}

    public String fetchDashboard(long userId) throws InterruptedException, java.util.concurrent.ExecutionException {
        try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {

            Future<UserProfile> userSubtask = scope.fork(() -> fetchUserProfile(userId));
            Future<UserOrders> ordersSubtask = scope.fork(() -> fetchUserOrders(userId));

            // Join blocks until both complete, or if one fails, it cancels the other
            scope.join();
            scope.throwIfFailed(e -> new RuntimeException("Dashboard aggregation failed", e));

            // Both succeeded safely
            return "User: " + userSubtask.get().name() + ", Orders: " + ordersSubtask.get().orderCount();
        }
    }

    private UserProfile fetchUserProfile(long id) { return new UserProfile("Alice", "Dark Mode"); }
    private UserOrders fetchUserOrders(long id) { return new UserOrders(5); }
}
